/**
 * Sets the default customer routing mode on existing sites (Task 21A).
 *
 * development_fixed serves deterministic recorded routes with no outbound HTTP;
 * live_cached is the cache-first Google path with its one-request controls. DDEV
 * forces development_fixed in code regardless of this value, so an existing
 * production site simply gains the explicit live_cached default it already
 * behaves as. Set only when unset, so a settings.php override is never
 * overwritten.
 */
function custom_webform_handlers_update_10045(): string {
  $config = \Drupal::configFactory()->getEditable('custom_webform_handlers.settings');
  if ($config->get('routing_mode') !== NULL) {
    return (string) t('Customer routing mode already set; nothing changed.');
  }

  $config->set('routing_mode', 'live_cached')->save();

  return (string) t('Set the default customer routing mode to live_cached.');
}

